from six import string_types


class AsnParser:
    """AsnParser command class."""

    def __init__(self):
        """Asnparser helper class."""

    @staticmethod
    def parse(axiom):
        """
        Parse given string into dictionary.

        :param axiom:       text to parse
        :type axiom:        str
        :return:            parsed axiom
        :rtype:             dict
        """
        return AsnParser._parse(AsnParser._get_value_between_brackets(axiom))

    @staticmethod
    def _strip(axiom):
        """
        Strip given axiom if possible.

        :param axiom:       text to parse
        :return:            parsed text
        """
        # if type(axiom) == str or type(axiom) == unicode:
        if isinstance(axiom, string_types):
            return axiom.strip()
        return axiom

    @staticmethod
    def _get_value_between_brackets(axiom):
        """
        Return content between '{' and '}'.

        :param axiom:   text to parse e.g axiom = "{ .... }"
        :type axiom:    string
        :return:        Value inside {}
        :rtype:         string
        """
        if axiom.find("{") < 0 or axiom.find("}") < 0:
            return None
        start = False
        depth = 0
        for index, character in enumerate(axiom):
            if character == "{":
                start = True
                depth += 1
            elif character == "}":
                depth -= 1
            if depth == 0 and start is True:
                return axiom[axiom.find("{") + 1: index].strip()
        return None

    @staticmethod
    def _should_elements_be_put_in_a_list(list_of_elements):
        """
        Distinguish if elements should be put in a list or dictionary.

        :param list_of_elements:    list of text to parse
        :type list_of_elements:     list
        :return:
            True    - elements between '{' and '}'         e.g [{a b},{c d}]
            False   - some element not between '{' and '}' e.g [a0 {a b} , a1 {c d}]
        :rtype:                     bool
        """
        for element in list_of_elements:
            if element[0] == "{" and element[-1] == "}":
                continue
            else:
                return False
        return True

    @staticmethod
    def _is_list_terminal(list_of_elements):
        """
        Distinguish if list of elements contains terminal values.

        :param list_of_elements: list of text to parse
        :type list_of_elements: list
        :return:
            True    - all elements in list are terminal
            False   - one of elements in list is no terminal
        :rtype: bool
        """
        for element in list_of_elements:
            if AsnParser._is_value_terminal(element):
                continue
            else:
                return False
        return True

    @staticmethod
    def _is_seperated_by_space(axiom):
        """
        Distinguish if axiom is seperated only by " " and no other character (like {}).

        :param axiom:       text to parse
        :type axiom:        string
        :return:
            True    - space is a separator      e.g " a b"
            False   - space is not a separator  e.g " {a b}"
        :rtype:             bool
        """
        for char in axiom.strip():
            if char == "{":
                return False
            elif char.isalpha() or char.isalnum() or char == "'" or char == "-":
                return True
            else:
                continue
        if axiom == '""':
            return True

    @staticmethod
    def _get_dictionary_of_elements(axiom):
        """
        Extract elements separated by ','.

        :param axiom:   text to parse
        :type axiom:    string
        :return:        dict of parsed axiom
        :rtype:         dict
        """
        if axiom.count("{") != axiom.count("}") or "," not in axiom:
            return None
        value = ""
        deep = 0
        list_of_elements = []
        for character in axiom:
            if character == "{":
                deep += 1
            elif character == "}":
                deep -= 1
            elif character == "," and deep == 0:
                list_of_elements.append(value.strip())
                value = ""
                continue
            value += character
        if list_of_elements and value:
            list_of_elements.append(value.strip())  # ADD LAST VALUE
            return AsnParser._parse_elements(list_of_elements)
        else:
            return None

    @staticmethod
    def _parse_elements(list_of_elements):
        """
        Parse given list of elements to dictionary or list.

        :param list_of_elements:    List of str with axioms
        :type list_of_elements:     list
        :return:
            list    - elements between '{' and '}'          e.g axiom  = [{a b},{c d}]
            dict    - some element not between '{' and '}'  e.g axiom = [a0 {a b} , a1 {c d}]
            list    - elements do not have the key          e.g axiom  = [2,4,4]
        :rtype:                     dict or list
        """
        elements_as_a_list = AsnParser._should_elements_be_put_in_a_list(list_of_elements)
        if elements_as_a_list:
            parsed_elements = []
            for element in list_of_elements:
                parsed_elements += AsnParser._parse(element)
            return parsed_elements
        elif AsnParser._is_list_terminal(list_of_elements):
            parsed_elements = []
            for element in list_of_elements:
                parsed_elements.append(AsnParser._parse(element))
            return parsed_elements
        elif not elements_as_a_list:
            parsed_elements = {}
            for element in list_of_elements:
                parsed_elements.update(AsnParser._parse(element))
            return parsed_elements

    @staticmethod
    def _is_value_terminal(axiom):
        """
        Distinguishes if axiom is terminal.

        :param axiom:   text to parse
        :type axiom:    str
        :return:
            True    - axiom is terminal
            False   - axiom is not terminal
        :rtype:         bool
        """
        if not axiom or not isinstance(axiom, string_types):
            return False
        separators = ":{} "
        for i in separators:
            if i in axiom:
                return False
        return True

    @staticmethod
    def _convert_to_hex_or_bin(axiom):
        """
        Convert to axiom to bin and hex.

        :param axiom:   text to parse e.g axiom = "278B798A'H"
        :type axiom:    str
        :return:
            0x278B79850A if axiom = "278B798A'H"
            0b10000000   if axiom = "10000000'B"
        :rtype:         str
        """
        if axiom[-1] == "B":
            return f"0b{axiom[1:-2]}"
        elif axiom[-1] == "H":
            return f"0x{axiom[1:-2]}"
        else:
            return axiom

    @staticmethod
    def _check_char(character):
        """
        Handle axiom based on the characters.

        :param character:       text to parse
        :return:                dict or list
        """

    @staticmethod
    def _return_value(key, value):
        """
        Handle value based on the key.

        :param key:         text to parse
        :param value:       text to parse
        :return:            dict or list
        """
        if not value:
            value = "{}"

        if key != ":":
            if key:
                return {AsnParser._strip(key): AsnParser._strip(value)}
            else:
                return [AsnParser._strip(value)]
        return [AsnParser._strip(value)]

    @staticmethod
    def _parse_opening_bracket(axiom):
        """
        Parse given axiom.

        :param axiom:       text to parse
        :type axiom:        str
        :return:            parsed axiom
        :rtype:             dict or list
        """
        value = AsnParser._get_value_between_brackets(axiom)
        if AsnParser._is_value_terminal(value):
            return [AsnParser._convert_to_hex_or_bin(value)]
        else:
            return AsnParser._parse(value)

    @staticmethod
    def _parse_axiom(axiom):
        """
        Parse given axiom recursively.

        :param axiom:       text to parse
        :type axiom:        str
        :return:            parsed axiom
        :rtype:             dict or list
        """
        key = ""
        value = ""
        for index, character in enumerate(axiom):
            if character == "{":
                value = AsnParser._parse_opening_bracket(axiom)

            elif character == " ":
                value = axiom[index:].strip()
                if AsnParser._is_seperated_by_space(value):
                    value = AsnParser._parse(value)
                else:
                    continue

            elif character == ":" and not key == "":
                continue
            elif character == "'":
                return AsnParser._convert_to_hex_or_bin(axiom)
            else:
                key = key + character
                continue

            return AsnParser._return_value(key, value)
        if key:
            return AsnParser._strip(key)

    @staticmethod
    def _parse(axiom):
        """
        Parse given axiom recursively.

        :param axiom:       text to parse
        :type axiom:        str
        :return:            parsed axiom
        :rtype:             dict or list
        """
        elements_dictionary = AsnParser._get_dictionary_of_elements(axiom)
        if elements_dictionary:
            for element in elements_dictionary:
                if element:
                    return elements_dictionary

        return AsnParser._parse_axiom(axiom)
